// Nhận payload từ node MQTT In (topic: smartdry/sensor/telemetry)
const data = typeof msg.payload === "string" ? JSON.parse(msg.payload) : msg.payload;
const rackStatusMap = ["ĐÃ THU VÀO MÁI HIÊN (0 độ)", "ĐANG PHƠI NGOÀI TRỜI (90 độ)"];
const weatherMap = {
    "NANG_RAO": "☀️ NẮNG RÁO (Đang phơi tốt)",
    "MUA_BONG_MAY": "🌦️ MƯA BÓNG MÂY (Đã thu sào tạm thời)",
    "MUA_RAO_LON": "⛈️ MƯA RÀO LỚN (Khóa an toàn ẩm)",
    "BAN_DEM": "🌙 BAN ĐÊM / SƯƠNG ĐÊM (Đã thu sào)"
};

// Lưu vết mốc giờ xoay sào ra (extend_timestamp) và thu sào vào (retract_timestamp) trong Flow Context
const prevState = flow.get("prev_rack_state");
let extendTimeStr = flow.get("extend_timestamp") || "08:15:00";
let retractTimeStr = flow.get("retract_timestamp") || "14:20:35";
const nowStr = new Date().toLocaleTimeString("vi-VN");

if (data.rack_state === 1 && prevState !== 1) {
    extendTimeStr = nowStr;
    flow.set("extend_timestamp", extendTimeStr);
} else if (data.rack_state === 0 && prevState === 1) {
    retractTimeStr = nowStr;
    flow.set("retract_timestamp", retractTimeStr);
}
flow.set("prev_rack_state", data.rack_state);

const formattedPayload = {
    temperature: Number(data.temp ?? 31.5),
    humidity: Number(data.hum ?? 64),
    rain_percent: Number(data.rain_pct ?? 5),
    weather_type: data.weather_type || "NANG_RAO",
    weather_label: weatherMap[data.weather_type] || data.weather_type || "☀️ NẮNG RÁO",
    drying_seconds: Number(data.drying_sec ?? 5420),
    drying_minutes: Number(data.drying_min ?? 90),
    drying_time_formatted: data.drying_time_str || "01:30:20",
    extended_at: extendTimeStr,
    retracted_at: retractTimeStr,
    fan_active: Boolean(data.fan),
    light_active: Boolean(data.light),
    rack_state: Number(data.rack_state ?? 1),
    rack_status_text: rackStatusMap[data.rack_state] || "ĐANG PHƠI NGOÀI TRỜI (90 độ)",
    wifi_rssi: Number(data.rssi ?? -58),
    device_ip: data.ip || "192.168.1.108",
    online_status: "🟢 ONLINE (MQTT Connected)",
    timestamp: new Date().toISOString()
};

// Khuyến nghị bật quạt sấy dựa trên thời gian đã phơi và độ ẩm (NC8)
let dryerAdvice = "Quần áo đang phơi nắng tự nhiên ngoài trời.";
if (formattedPayload.rack_state === 0) {
    if (formattedPayload.drying_minutes < 120 && formattedPayload.humidity >= 75) {
        dryerAdvice = "⚠️ Đồ mới phơi " + formattedPayload.drying_minutes + " phút & Độ ẩm cao (" + formattedPayload.humidity + "%) -> NÊN BẬT QUẠT SẤY!";
    } else {
        dryerAdvice = "✅ Sào đã thu vào mái hiên. Có thể bật quạt sấy nếu đồ còn ẩm.";
    }
}

return [
    { payload: formattedPayload.wifi_rssi },
    { payload: formattedPayload.device_ip },
    { payload: formattedPayload.online_status },
    { payload: formattedPayload.temperature, topic: "Nhiệt độ (°C)" },
    { payload: formattedPayload.humidity, topic: "Độ ẩm (%)" },
    { payload: formattedPayload.rain_percent },
    { payload: formattedPayload.weather_label },
    { payload: formattedPayload.rack_status_text },
    { payload: formattedPayload.extended_at },
    { payload: formattedPayload.retracted_at },
    { payload: formattedPayload.drying_time_formatted },
    { payload: dryerAdvice },
    { payload: formattedPayload }
];

const act = msg.payload && msg.payload.action;
const nowStr = new Date().toLocaleTimeString("vi-VN");
if (act === "EXTEND") {
    flow.set("extend_timestamp", nowStr);
    flow.set("prev_rack_state", 1);
    return [
        { payload: "ĐANG PHƠI NGOÀI TRỜI (90 độ)" },
        { payload: nowStr },
        null,
        null
    ];
} else if (act === "RETRACT") {
    flow.set("retract_timestamp", nowStr);
    flow.set("prev_rack_state", 0);
    return [
        { payload: "ĐÃ THU VÀO MÁI HIÊN (0 độ)" },
        null,
        { payload: nowStr },
        null
    ];
} else if (act === "RESET_TIMER") {
    return [
        null,
        null,
        null,
        { payload: "00:00:00" }
    ];
}
return null;

const now = Date.now();
const tempPoints = [];
const humPoints = [];
const hours = [8, 9, 10, 11, 12, 13, 14];
const temps = [28.5, 30.0, 31.8, 33.2, 34.0, 32.5, 29.5];
const hums  = [74,   68,   62,   56,   53,   60,   78];

for (let i = 0; i < hours.length; i++) {
    const t = now - (hours.length - 1 - i) * 600000;
    tempPoints.push({ x: t, y: temps[i] });
    humPoints.push({ x: t, y: hums[i] });
}

const lineChartData = [{
    series: ["Nhiệt độ (°C)", "Độ ẩm (%)"],
    data: [tempPoints, humPoints],
    labels: ["Nhiệt độ (°C)", "Độ ẩm (%)"]
}];

const barChartData = [{
    series: ["Thời gian phơi thực tế (Phút)"],
    data: [[145, 95, 180, 40, 125]],
    labels: ["Hôm qua (Sáng)", "Hôm qua (Chiều)", "Hôm nay (Đợt 1)", "Đợt 2 (Mưa bóng mây)", "Đợt 3 (Hiện tại)"]
}];

const initialTelemetry = {
    temp: 32.5,
    hum: 62,
    rain_pct: 5,
    weather_type: "NANG_RAO",
    drying_sec: 7520,
    drying_min: 125,
    drying_time_str: "02:05:20",
    fan: false,
    light: false,
    rssi: -56,
    ip: "192.168.1.108",
    rack_state: 1
};

return [
    { payload: lineChartData },
    { payload: barChartData },
    { payload: initialTelemetry }
];

msg.payload = {
    type: "RAIN_DETECTED",
    message: "Mưa rào lớn bất chợt! Đã tự động xoay Servo thu sào về góc 0 độ.",
    drying_time_str: "00:25:00",
    drying_minutes: 25
};
return msg;

// Nhận payload từ node MQTT In (topic: smartdry/alert/emergency)
const alert = typeof msg.payload === "string" ? JSON.parse(msg.payload) : msg.payload;
const extendAt = flow.get("extend_timestamp") || "08:15:00";
const retractAt = new Date().toLocaleTimeString("vi-VN");

// Nhánh 1: Tạo request gửi PushSafer Notification về điện thoại
const pushMsg = {
    payload: {
        k: env.get("PUSHSAFER_PRIVATE_KEY") || "YOUR_PUSHSAFER_KEY",
        t: "CẢNH BÁO MƯA - AERODRY IOT",
        m: `${alert.message} | Giờ mở: ${extendAt} - Giờ thu: ${retractAt} | Đã phơi: ${alert.drying_time_str || "00:25:00"}`,
        s: "25",
        v: "3",
        i: "5"
    }
};

// Nhánh 2: Tạo nội dung gửi Email qua Node-RED SMTP Email Node
const emailMsg = {
    topic: `[AeroDry IoT - CẢNH BÁO MƯA] Đã tự động thu sào (Thời gian đã phơi: ${alert.drying_time_str || "00:25:00"})`,
    payload: `Hệ thống giàn phơi thông minh AeroDry IoT vừa phát hiện trời mưa và tự động thu sào vào mái hiên:\n\n` +
             `- Trạng thái: ${alert.message}\n` +
             `- Thời điểm xoay sào ra phơi (90 độ): ${extendAt}\n` +
             `- Thời điểm thu sào vào mái hiên (0 độ): ${retractAt}\n` +
             `- Tổng thời gian quần áo đã phơi thực tế: ${alert.drying_time_str || "00:25:00"} (${alert.drying_minutes || 25} phút)\n\n` +
             `Người dùng vui lòng truy cập Website Dashboard để quyết định bật Quạt sấy đối lưu nếu quần áo chưa khô!`
};

// Nhánh 3: Hiển thị thông báo khẩn cấp ngay trên Web Dashboard
const toastMsg = {
    topic: "⛈️ CẢNH BÁO MƯA KHẨN CẤP - ĐÃ THU SÀO (0°)",
    payload: `${alert.message} Tổng thời gian đã phơi: ${alert.drying_time_str || "00:25:00"}. Bạn có muốn bật Quạt sấy đối lưu?`
};

return [pushMsg, emailMsg, toastMsg];

if (msg.topic === "email") {
    flow.set("login_email", msg.payload);
    return null;
}
if (msg.topic === "password") {
    flow.set("login_password", msg.payload);
    return null;
}
if (msg.topic === "login_action") {
    const email = flow.get("login_email") || "admin@aerodry.iot";
    flow.set("is_authenticated", true);
    return [
        { payload: "Đã xác thực (" + email + ") - Quyền điều khiển: ACTIVE" },
        { payload: { tab: "2. Bảng điều khiển trung tâm (Main Dashboard)" } },
        { topic: "Đăng nhập thành công", payload: "Chào mừng " + email + "! Đang chuyển tới Bảng điều khiển trung tâm..." }
    ];
}
return null;

if (msg.topic === 'smartdry/control/rack') {
    return [msg, null, null, null, null];
} else if (msg.topic === 'smartdry/control/dryer') {
    return [null, msg, null, null, null];
} else if (msg.topic === 'smartdry/sensor/telemetry') {
    const triggerAlert = msg.payload && msg.payload.trigger_alert ? msg : null;
    return [null, null, msg, triggerAlert, null];
} else if (msg.topic === 'login_action') {
    return [null, null, null, null, msg];
}
return null;
